(function(root){
const icon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m12 3 9 5-9 5-9-5 9-5ZM3 12l9 5 9-5M3 16l9 5 9-5"/></svg>';
function mount({map,layers}){const host=document.createElement('div');host.className='transit-map-controls';host.innerHTML='<div class="transit-map-toolbar"><button type="button" class="transit-control-icon" aria-label="Map layers" aria-expanded="false">'+icon+'</button></div><section class="transit-control-panel" aria-label="Map layers" hidden><header><h3>Map layers</h3><button type="button" class="transit-panel-hide">Hide</button></header><fieldset><legend class="transit-visually-hidden">Basemap</legend></fieldset></section>';map.getContainer().parentElement.append(host);L.DomEvent.disableClickPropagation(host);L.DomEvent.disableScrollPropagation(host);const button=host.querySelector('[aria-label="Map layers"]'),panel=host.querySelector('section'),hide=panel.querySelector('button');function close(){panel.hidden=true;button.setAttribute('aria-expanded','false');button.focus()}button.onclick=()=>{panel.hidden=!panel.hidden;button.setAttribute('aria-expanded',String(!panel.hidden))};hide.onclick=close;host.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
for(const [name,layer]of Object.entries(layers)){const label=document.createElement('label'),radio=document.createElement('input'),text=document.createElement('span');label.className='transit-basemap-option';radio.type='radio';radio.name='transit-basemap';radio.value=name;radio.checked=map.hasLayer(layer);text.textContent=name;label.append(radio,text);panel.querySelector('fieldset').append(label);radio.onchange=()=>{if(!radio.checked)return;for(const candidate of Object.values(layers))if(map.hasLayer(candidate))map.removeLayer(candidate);layer.addTo(map)};map.on('baselayerchange',()=>radio.checked=map.hasLayer(layer))}
}root.SiegTransitControls={mount};})(window);
